script:
(function () {
  'use strict';
  // Debt payoff: avalanche vs snowball vs minimum payments only.
  // Each month every open debt is charged interest = balance x APR / 12 (rounded to the cent),
  // then receives its own minimum payment (capped at what it owes). In the avalanche and snowball
  // plans the monthly budget stays fixed at (sum of all minimums + extra payment), so whatever is
  // left after the minimums - including the minimums of debts already paid off - goes to the
  // target debt: highest APR first (avalanche, ties -> smaller balance) or smallest starting
  // balance first (snowball, ties -> higher APR). "Minimums only" pays each debt its own minimum
  // with no extra and no rollover. Minimum payments are treated as fixed amounts.
  // Verified (scratchpad w2debt/dp.test.js):
  //   one debt of $10,000 at 12% with a $222.45 minimum (closed-form level payment
  //   rB / (1 - (1 + r)^-60) = $222.44, rounded up) -> 60 months, interest within $0.10 of the
  //   closed form (cent rounding of each month's interest);
  //   a two-debt case ($1,000 at 12% min $50, $500 at 24% min $25, $100 extra) re-done in plain
  //   code month by month -> both 10 months and $90.40 interest, the 24% debt cleared in month 5;
  //   with zero interest the payoff month equals total debt / budget, rounded up;
  //   avalanche interest <= snowball interest across 2,000 random debt sets, and total paid =
  //   starting balances + interest in every plan;
  //   default example ($21,700 over four debts, $200 extra): avalanche 29 months and $3,960.55
  //   interest; snowball 30 months and $4,315.41; minimums only 58 months and $7,645.93.
  var MAX_MONTHS = 1200;
  var MAX_DEBTS = 10;
  var DEFAULTS = [
    { name: 'Credit card', balance: 6500, apr: 24.99, min: 195 },
    { name: 'Store card', balance: 1200, apr: 29.99, min: 45 },
    { name: 'Car loan', balance: 9800, apr: 7.9, min: 310 },
    { name: 'Personal loan', balance: 4200, apr: 13.5, min: 145 }
  ];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var monthName = new Intl.DateTimeFormat('en-US', { month: 'short', year: 'numeric' });
  var rowCounter = 0;

  function cents(x) { return Math.round(x * 100) / 100; }

  function payoffOrder(debts, strategy) {
    var idx = debts.map(function (d, i) { return i; });
    idx.sort(function (a, b) {
      var da = debts[a], db = debts[b];
      if (strategy === 'avalanche') return (db.apr - da.apr) || (da.balance - db.balance) || (a - b);
      return (da.balance - db.balance) || (db.apr - da.apr) || (a - b);
    });
    return idx;
  }

  // debts: [{ balance, apr (decimal), min }]; strategy: 'minimum' | 'avalanche' | 'snowball'.
  function simulate(debts, extra, strategy) {
    var n = debts.length, bal = debts.map(function (d) { return d.balance; });
    var paidOffMonth = debts.map(function (d) { return d.balance > 0.005 ? 0 : -1; });
    var order = payoffOrder(debts, strategy);
    var budget = debts.reduce(function (s, d) { return s + d.min; }, 0) + extra;
    var totalInterest = 0, totalPaid = 0, yearEnd = [];
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var open = 0;
      for (var i = 0; i < n; i++) {
        if (bal[i] <= 0.005) continue;
        var interest = cents(bal[i] * debts[i].apr / 12);
        bal[i] += interest;
        totalInterest += interest;
      }
      var avail = budget;
      for (i = 0; i < n; i++) {
        if (bal[i] <= 0.005) continue;
        var pay = Math.min(debts[i].min, bal[i]);
        bal[i] -= pay; avail -= pay; totalPaid += pay;
      }
      if (strategy !== 'minimum') {
        for (var k = 0; k < n && avail > 0.005; k++) {
          var j = order[k];
          if (bal[j] <= 0.005) continue;
          var more = Math.min(avail, bal[j]);
          bal[j] -= more; avail -= more; totalPaid += more;
        }
      }
      for (i = 0; i < n; i++) {
        if (bal[i] <= 0.005) { if (paidOffMonth[i] === 0) paidOffMonth[i] = m; bal[i] = 0; } else open++;
      }
      if (m % 12 === 0 || open === 0) yearEnd.push(bal.reduce(function (s, b) { return s + b; }, 0));
      if (open === 0) return { paidOff: true, months: m, interest: totalInterest, paid: totalPaid, payoffMonth: paidOffMonth, yearEnd: yearEnd };
    }
    return { paidOff: false, months: MAX_MONTHS, interest: totalInterest, paid: totalPaid, payoffMonth: paidOffMonth, yearEnd: yearEnd };
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function dateAfter(months) {
    var now = new Date();
    return monthName.format(new Date(now.getFullYear(), now.getMonth() + months, 1));
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) {
      var td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    });
    body.appendChild(tr);
  }

  // ---- Debt rows (built with DOM methods; user text is only ever set as values/textContent) ----
  function el(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text) e.textContent = text;
    return e;
  }

  function numberField(id, label, value, affix, affixFirst, step, max) {
    var wrap = el('div');
    var lab = el('label', 'form-label', label);
    lab.setAttribute('for', id);
    var group = el('div', 'input-group');
    var input = el('input', 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none');
    input.type = 'number'; input.id = id; input.min = '0'; input.step = step; input.inputMode = 'decimal';
    if (max) input.max = max;
    input.value = value === '' ? '' : String(value);
    var a = el('span', 'input-affix', affix);
    if (affixFirst) { group.appendChild(a); group.appendChild(input); } else { group.appendChild(input); group.appendChild(a); }
    wrap.appendChild(lab); wrap.appendChild(group);
    return wrap;
  }

  function addDebtRow(d) {
    var list = document.getElementById('dpDebts');
    rowCounter++;
    var n = rowCounter;
    var row = el('div', 'space-y-3 rounded-xl border border-line p-4');
    row.setAttribute('data-debt-row', String(n));
    var head = el('div', 'flex items-center justify-between gap-3');
    var title = el('p', 'text-sm font-semibold text-ink', 'Debt');
    title.setAttribute('data-debt-title', '');
    var remove = el('button', 'button-secondary h-9 px-3 text-sm', 'Remove');
    remove.type = 'button';
    remove.setAttribute('data-remove', '');
    remove.addEventListener('click', function () {
      if (list.querySelectorAll('[data-debt-row]').length <= 1) return;
      row.remove();
      refreshRows();
      update();
    });
    head.appendChild(title); head.appendChild(remove);
    row.appendChild(head);

    var nameWrap = el('div');
    var nameLabel = el('label', 'form-label', 'Name');
    nameLabel.setAttribute('for', 'dpName' + n);
    var name = el('input', 'form-control');
    name.type = 'text'; name.id = 'dpName' + n; name.maxLength = 40; name.autocomplete = 'off';
    name.placeholder = 'e.g. Visa card';
    name.value = d.name || '';
    nameWrap.appendChild(nameLabel); nameWrap.appendChild(name);
    row.appendChild(nameWrap);

    var pair = el('div', 'form-row form-row-2');
    pair.appendChild(numberField('dpBal' + n, 'Balance', d.balance, '$', true, '100'));
    pair.appendChild(numberField('dpApr' + n, 'APR', d.apr, '%', false, '0.1', '100'));
    row.appendChild(pair);
    row.appendChild(numberField('dpMin' + n, 'Minimum monthly payment', d.min, '$', true, '5'));
    list.appendChild(row);
    refreshRows();
  }

  function refreshRows() {
    var rows = document.getElementById('dpDebts').querySelectorAll('[data-debt-row]');
    rows.forEach(function (row, i) {
      row.querySelector('[data-debt-title]').textContent = 'Debt ' + (i + 1);
      var btn = row.querySelector('[data-remove]');
      btn.disabled = rows.length <= 1;
      btn.setAttribute('aria-label', 'Remove debt ' + (i + 1));
    });
    document.getElementById('dpAdd').disabled = rows.length >= MAX_DEBTS;
  }

  function readDebts() {
    var out = [], ok = true;
    var rows = document.getElementById('dpDebts').querySelectorAll('[data-debt-row]');
    rows.forEach(function (row, i) {
      var n = row.getAttribute('data-debt-row');
      var name = document.getElementById('dpName' + n).value.trim() || ('Debt ' + (i + 1));
      var balEl = document.getElementById('dpBal' + n), aprEl = document.getElementById('dpApr' + n), minEl = document.getElementById('dpMin' + n);
      var bal = parseFloat(balEl.value), apr = parseFloat(aprEl.value), min = parseFloat(minEl.value);
      if (balEl.value.trim() === '' || bal === 0) {
        [balEl, aprEl, minEl].forEach(function (e) { e.setAttribute('aria-invalid', 'false'); });
        return; // empty row: ignored
      }
      var badBal = isNaN(bal) || bal < 0 || bal > 1e8, badApr = isNaN(apr) || apr < 0 || apr > 100, badMin = isNaN(min) || min <= 0;
      balEl.setAttribute('aria-invalid', String(badBal));
      aprEl.setAttribute('aria-invalid', String(badApr));
      minEl.setAttribute('aria-invalid', String(badMin));
      if (badBal || badApr || badMin) { ok = false; return; }
      out.push({ name: name, balance: bal, apr: apr / 100, min: min });
    });
    return { ok: ok, debts: out };
  }

  function clearResults() {
    ['dpAvTime', 'dpAvInterest', 'dpSaved', 'dpDiff'].forEach(function (id) { set(id, '–'); });
    set('dpAvNote', ''); set('dpDiffNote', '');
    clearBody('dpCompare'); clearBody('dpOrder'); clearBody('dpYears');
  }

  function update() {
    var error = document.getElementById('dpError');
    var extra = parseFloat(document.getElementById('dpExtra').value);
    if (document.getElementById('dpExtra').value.trim() === '') extra = 0;
    var input = readDebts();
    var problem = '';
    if (!input.ok) problem = 'Check the highlighted debts: balances of $0 or more, APRs from 0 to 100% and minimum payments above $0.';
    else if (!input.debts.length) problem = 'Enter at least one debt with a balance above $0.';
    else if (isNaN(extra) || extra < 0) problem = 'Enter an extra monthly payment of $0 or more.';
    if (problem) { error.hidden = false; error.textContent = problem; clearResults(); return; }

    var debts = input.debts;
    var av = simulate(debts, extra, 'avalanche'), sb = simulate(debts, extra, 'snowball'), mn = simulate(debts, 0, 'minimum');
    if (!av.paidOff) {
      error.hidden = false;
      error.textContent = 'Your total monthly payment does not keep up with the interest, so these debts are not paid off within 100 years. Raise the minimum or extra payments.';
      clearResults();
      return;
    }
    error.hidden = true;
    error.textContent = '';
    set('dpAvTime', duration(av.months));
    set('dpAvNote', 'Debt-free by ' + dateAfter(av.months) + '.');
    set('dpAvInterest', money.format(av.interest));
    set('dpSaved', mn.paidOff ? money.format(Math.max(mn.interest - av.interest, 0)) : 'Not comparable');
    var diff = sb.interest - av.interest;
    set('dpDiff', money.format(Math.abs(diff)));
    set('dpDiffNote', Math.abs(diff) < 0.005 ? 'Both plans cost the same here.'
      : (diff > 0 ? 'Extra interest the snowball costs' : 'Interest the snowball saves') +
        (sb.months !== av.months ? '; it finishes ' + duration(Math.abs(sb.months - av.months)) + (sb.months > av.months ? ' later.' : ' sooner.') : '; same finish date.'));

    var compare = clearBody('dpCompare');
    [['Avalanche (highest APR first)', av], ['Snowball (smallest balance first)', sb], ['Minimum payments only', mn]].forEach(function (p) {
      var s = p[1];
      addRow(compare, [p[0], s.paidOff ? duration(s.months) : 'Over 100 years', s.paidOff ? dateAfter(s.months) : '–',
        s.paidOff ? money.format(s.interest) : '–', s.paidOff ? money.format(s.paid) : '–']);
    });
    var minNote = document.getElementById('dpMinNote');
    minNote.hidden = mn.paidOff;
    if (!mn.paidOff) minNote.textContent = 'At least one minimum payment does not cover that debt’s monthly interest, so minimum payments alone never clear it.';

    var order = clearBody('dpOrder');
    var avOrder = payoffOrder(debts, 'avalanche');
    avOrder.forEach(function (i) {
      var d = debts[i];
      addRow(order, [d.name, money.format(d.balance), (d.apr * 100).toFixed(2).replace(/\.?0+$/, '') + '%',
        dateAfter(av.payoffMonth[i]) + ' (month ' + av.payoffMonth[i] + ')',
        dateAfter(sb.payoffMonth[i]) + ' (month ' + sb.payoffMonth[i] + ')']);
    });

    var years = clearBody('dpYears');
    var total = debts.reduce(function (s, d) { return s + d.balance; }, 0);
    var count = Math.max(av.yearEnd.length, sb.yearEnd.length, mn.paidOff ? mn.yearEnd.length : 0);
    function at(s, y) { return y < s.yearEnd.length ? s.yearEnd[y] : (s.paidOff ? 0 : NaN); }
    addRow(years, ['Today', money.format(total), money.format(total), money.format(total)]);
    for (var y = 0; y < count; y++) {
      var vm = at(mn, y);
      addRow(years, ['Year ' + (y + 1), money.format(at(av, y)), money.format(at(sb, y)), isNaN(vm) ? '–' : money.format(vm)]);
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    DEFAULTS.forEach(addDebtRow);
    var form = document.getElementById('dpForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    document.getElementById('dpAdd').addEventListener('click', function () {
      if (document.getElementById('dpDebts').querySelectorAll('[data-debt-row]').length >= MAX_DEBTS) return;
      addDebtRow({ name: '', balance: '', apr: '', min: '' });
      update();
    });
    update();
  });
})();
